package com.drivique.api.model; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="vehicle_ratings",schema="rental",uniqueConstraints=@UniqueConstraint(name="uq_vehicle_ratings_reservation",columnNames="reservation_id")) public class VehicleRating{@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="reservation_id",nullable=false) private Reservation reservation;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="vehicle_id",nullable=false) private Vehicle vehicle;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user;@Column(nullable=false) private short rating;@Column(length=1000) private String comment;@Column(name="created_at",nullable=false,updatable=false) private Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now();protected VehicleRating(){} public VehicleRating(Reservation r,Vehicle v,User u,short rating,String comment){reservation=r;vehicle=v;user=u;this.rating=rating;this.comment=comment;}public UUID getId(){return id;}public User getUser(){return user;}public short getRating(){return rating;}public String getComment(){return comment;}public Instant getCreatedAt(){return createdAt;}}
